from lib import *
S = SS('g94')
steps = [
    step("结果没被使用时,编译器能把整个调用删掉(go test -bench,-benchtime=200ms)。BenchmarkPop_NoSink(循环里调用能内联的 Pop,不使用结果):0.297 ns/op;BenchmarkPop_Sink(结果赋给全局变量):0.340 ns/op;BenchmarkPop_Loop(同样不使用结果,但用 for b.Loop()):2.350 ns/op;对照 BenchmarkSlow_NoSink(函数标了 //go:noinline,调用不会被消除):25.850 ns/op。0.297 ns 比一个 CPU 周期还短,说明循环里根本没在干活。", t=tl(S(1)), mark=lidx(S(1), 'Pop_NoSink', 'Pop_Sink'), done=lidx(S(1), 'Pop_Loop', 'Slow_NoSink'), b=bars([['Pop_NoSink (ns/op)', 0.297, '0.297'], ['Pop_Sink', 0.340, '0.340'], ['Pop_Loop(b.Loop)', 2.350, '2.350'], ['Slow_NoSink(noinline)', 25.850, '25.850']], 25.85, mark=[0, 1], done=[2, 3]), kv=KV([['不使用结果', '0.297 ns,循环空转'], ['b.Loop', '2.350 ns,调用被保住'], ['noinline 的慢函数', '25.850 ns,是真实成本']], ['不使用结果'])),
    step("参数是常量,函数又能内联时,结果被折叠成常量:BenchmarkMul_ConstArgs(Mul(123, 456),结果赋给全局变量):0.309 ns/op;BenchmarkMul_VarArgs(参数含循环变量):0.447 ns/op;BenchmarkMul_ConstArgsLoop(常量参数,for b.Loop()):2.128 ns/op。", t=tl(S(2)), mark=lidx(S(2), 'ConstArgs  ', 'VarArgs'), done=lidx(S(2), 'ConstArgsLoop'), b=bars([['Mul 常量参数 (ns)', 0.309, '0.309'], ['Mul 变量参数', 0.447, '0.447'], ['Mul 常量参数 + b.Loop', 2.128, '2.128']], 2.128, mark=[0, 1], done=[2]), kv=KV([['常量参数', '0.309 ns,调用已被折叠'], ['b.Loop', '2.128 ns,参数被保住']], ['b.Loop'])),
    step("同一份数据反复排序:BenchmarkSort_SameSlice(每次对同一个切片 sort.Ints,第一次之后排的都是已经排好的数据):7635 ns/op;BenchmarkSort_FreshCopy(每次 StopTimer 后复制原始数据,StartTimer 再排序):462796 ns/op;BenchmarkSort_FreshCopyNoStop(复制和排序都计时):421463 ns/op。第一种比后两种小了约 60 倍,测的根本不是排序随机数据。", t=tl(S(3)), mark=lidx(S(3), 'SameSlice'), done=lidx(S(3), 'FreshCopy  ', 'FreshCopyNoStop'), b=bars([['SameSlice (ns/op)', 7635, '7635'], ['FreshCopy', 462796, '462796'], ['FreshCopyNoStop', 421463, '421463']], 462796, mark=[0], done=[1, 2]), kv=KV([['同一切片反复排序', '7635 ns(排好的数据)'], ['每次用新副本', '约 42–46 万 ns'], ['结论', '被测的输入每次迭代都不能变']], ['结论'])),
    step("同一个基准重复运行的波动(BenchmarkSort_FreshCopyNoStop,-count=10):10 次的 ns/op 依次是 368448 365389 369454 368951 366887 365990 360273 362217 375844 431496;最小 360273 / 中位 367668 / 最大 431496,最大/最小 = 1.20。注意它比上一节同一个基准的 421463 ns 也有明显差距(那是另一次独立运行)。", t=tl(S(4)), mark=lidx(S(4), '最小 360273'), b=bars([['最小 (ns)', 360273, '360273'], ['中位', 367668, '367668'], ['最大', 431496, '431496']], 431496, done=[0, 1], mark=[2]), kv=KV([['10 次的范围', '360273–431496 ns'], ['最大/最小', '1.20'], ['含义', '单次测量的差别小于 20% 不能当结论']], ['含义'])),
    step("汇编里看循环体(go test -c 后 go tool objdump):BenchmarkPop_NoSink 的机器指令一共 8 条,其中调用 Pop 或 OnesCount64 的 CALL 指令 0 条、popcount(CNT)类指令 0 条——只剩 MOVD、JMP、ADD、CMP、BLT、RET,也就是一个空循环;BenchmarkPop_Sink 有 12 条指令,含 1 条 VCNT。", t=tl(S(5)), mark=lidx(S(5), 'BenchmarkPop_NoSink 的机器指令共 8 条'), done=lidx(S(5), 'BenchmarkPop_Sink 的机器指令共 12 条'), kv=KV([['NoSink', '8 条指令,没有 CALL,没有 VCNT:空循环'], ['Sink', '12 条指令,含 1 条 VCNT']], ['NoSink'])),
    step("testing.B.Loop 的文档:在 for b.Loop() { … } 循环体里,函数调用的参数与结果、被赋值的变量都会被保持存活,防止编译器完全优化掉循环体;目前实现为一个编译器变换,把这些变量用 runtime.KeepAlive 内建调用包起来;只作用于循环花括号之间的语句,循环条件必须正好写成 b.Loop()。", t=tl(S(6)), done=lidx(S(6), 'kept alive', 'arguments to and results'), mark=lidx(S(6), 'Within the body of a'), kv=KV([['作用', '保住循环体里的参数和结果'], ['实现', '编译器插入 runtime.KeepAlive'], ['写法', '条件必须正好是 b.Loop()']], ['写法'])),
]
A = mkartg('g94', 94, 'Go,基准测试,编译器优化,b.Loop,testing,真实验证,动画演示',
    '在 Go 1.27.1(arm64 macOS)里复现基准测试的陷阱:不使用结果时能内联的函数被整个删掉,循环体只剩 8 条指令(0.297 ns/op),b.Loop 版本保住了调用(2.350 ns/op),noinline 的同类函数是 25.850 ns/op;常量参数被折叠成常量;对同一个切片反复排序测的是已排序数据(7635 ns 对 462796 ns);同一个基准重复 10 次最大与最小差 20%。',
    '基准测试得到的数字有时好得不真实:0.3 ns 一次的“函数调用”比一个 CPU 周期还短。这篇复现几个最常见的陷阱——被编译器优化掉、常量折叠、被测数据被上一次迭代改变——并用汇编证明循环里真的什么都没做,再看 Go 1.24 的 b.Loop 怎么堵这个洞。',
    [('0.297 ns', '不使用结果时,一个能内联的函数的基准耗时:比一个时钟周期还短,说明调用已被消除'), ('7635 vs 462796 ns', '反复对同一个切片排序与每次用新副本排序'), ('1.20', '同一个基准重复 10 次,最大耗时与最小耗时之比')],
    [('调用被整个删掉', '<p>结果没被使用、函数又能内联,编译器就把调用删掉了:这个基准只有 0.297 ns/op,比一个时钟周期还短。把结果赋给全局变量是 0.340 ns(popcount 本身只要一条指令,所以差别很小);标了 <code>//go:noinline</code> 的同类函数 25.850 ns 才是真实的计算成本。用 <code>for b.Loop()</code> 写同样不使用结果的基准是 2.350 ns,调用没有被删(原因见最后一节)。</p>'),
     ('常量参数', '<p><code>Mul(123, 456)</code> 这种常量参数的调用在编译期被折叠成常量,0.309 ns;换成含循环变量的参数是 0.447 ns,依然很小,因为乘法本身就一条指令。要测的函数必须用运行时才知道的输入。</p>'),
     ('输入被改变', '<p>对同一个切片反复 <code>sort.Ints</code>,第一次之后排的是已经排好的数据:7635 ns,比用新副本的 462796 ns 小了约 60 倍。基准里被测的输入每次迭代都要一样。<code>StopTimer</code>/<code>StartTimer</code> 能把复制排除在计时之外,但它自己有开销,我这里没有量。</p>'),
     ('噪声', '<p>同一个基准连续 10 次:360273 到 431496 ns,最大/最小 1.20;还和前一节同一个基准的单次结果(421463)差了一截。比较两个版本时,差别小于 20% 的单次结果不能当结论,要多次运行并用统计工具(本文没有用 benchstat)。</p>'),
     ('汇编证据', '<p>BenchmarkPop_NoSink 的循环体只有 8 条指令(MOVD、JMP、ADD、CMP、BLT、RET),没有 CALL,也没有 popcount 指令;而把结果赋给全局变量的版本有 12 条指令,含 1 条 <code>VCNT</code>。看到小于一个时钟周期的数字就该去看汇编。</p>'),
     ('b.Loop', '<p>文档说 <code>for b.Loop()</code> 的循环体里,函数调用的参数与结果、被赋值的变量都会被 <code>runtime.KeepAlive</code> 保住,所以不使用结果也不会被删:实验里同样的调用是 2.350 ns(常量参数的 Mul 是 2.128 ns)。这 2 ns 里包含 <code>b.Loop</code> 本身的每次迭代开销,我没有把两部分拆开量,所以比较极小的函数时要意识到这个底噪。</p>')],
    steps,
    [ENV_G + '。基准用 go test -bench -benchtime=200ms -benchmem;汇编用 go test -c 与 go tool objdump;重复运行用 -count=10;读过的文档:go doc testing.B.Loop',
     '没有验证:benchstat 的显著性判断、-cpuprofile 辅助检查基准、更大的函数体里被部分消除的情形、b.Loop 与 for b.N 在更长的被测函数上的差别、Linux 与其它架构上的结果'],
    '基准测试的陷阱')
